<?php require_once "../db.php";require_role("Teacher");$id=(int)($_GET["id"]??0);$uid=current_id();$s=$conn->prepare("SELECT * FROM quiz WHERE id=? AND created_by=?");$s->bind_param("ii",$id,$uid);$s->execute();$q=$s->get_result()->fetch_assoc();if(!$q)die("Quiz not found.");if($_SERVER["REQUEST_METHOD"]==="POST"){$title=trim($_POST["title"]);$subject=trim($_POST["subject"]);$desc=trim($_POST["description"]);$duration=(int)$_POST["duration"];$x=$conn->prepare("UPDATE quiz SET title=?,subject=?,description=?,duration=? WHERE id=? AND created_by=?");$x->bind_param("sssiii",$title,$subject,$desc,$duration,$id,$uid);$x->execute();go("manage_quiz.php");}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Quiz</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/style.css" rel="stylesheet"></head><body><div class="container py-5"><div class="card panel-card col-lg-8 mx-auto"><div class="card-body p-4"><h2>Edit Quiz</h2><form method="post"><input name="title" value="<?=e($q["title"])?>" class="form-control mb-3" required><input name="subject" value="<?=e($q["subject"])?>" class="form-control mb-3"><textarea name="description" class="form-control mb-3"><?=e($q["description"])?></textarea><input type="number" name="duration" value="<?=$q["duration"]?>" class="form-control mb-3"><button class="btn btn-primary">Update</button></form></div></div></div></body></html>
